from native_file_markers import read_native_file_marker
import argparse,json,os,pathlib,signal,subprocess,tempfile,time
p=argparse.ArgumentParser();p.add_argument('--executable',required=True,type=pathlib.Path);p.add_argument('--sdk-directory',required=True,type=pathlib.Path);p.add_argument('--library',required=True,type=pathlib.Path);p.add_argument('--directory',required=True,type=pathlib.Path);p.add_argument('--node',required=True);a=p.parse_args();receipt=a.directory.resolve();receipt.mkdir(parents=True,exist_ok=True);out=pathlib.Path(tempfile.mkdtemp(prefix='cases-',dir=receipt));sdk=a.sdk_directory.resolve();rows=[]
def until(fn,seconds=6):
 end=time.monotonic()+seconds
 while not fn():assert time.monotonic()<end,'actual native marker/exit absent';time.sleep(.002)
def state(pid):
 try:return pathlib.Path('/proc',str(pid),'stat').read_text().rsplit(')',1)[1].split()[0]
 except FileNotFoundError:return None
def files(root):return[p for d in root.glob('suitecut-attachments-*')for p in d.rglob('*')if p.is_file()]
common="import{defineNativeSuite}from "+json.dumps((sdk/'native.js').as_uri())+";import{strict as assert}from'node:assert';import{existsSync,writeFileSync}from'node:fs';import{setTimeout as wait}from'node:timers/promises';const held=async()=>{while(!existsSync(process.env.SUITECUT_ATTACHMENT_TEST_MARKER))await wait(1)};"
def start(name,body,hold='file'):
 root=out/name;root.mkdir();suite=root/'suite.mjs';suite.write_text(common+body);env=dict(os.environ,LD_PRELOAD=str(a.library),SUITECUT_ATTACHMENT_TEST_HOLD=hold,SUITECUT_ATTACHMENT_TEST_MARKER=str(root/'syscall.marker'),SUITECUT_ATTACHMENT_TEST_RELEASE=str(root/'release'),ACTUAL_RAW_RETURN=str(root/'raw-return'),ACTUAL_ALLOW_EXIT=str(root/'allow-exit'))
 process=subprocess.Popen([str(a.executable),'--node',a.node,'--host-script',str(sdk/'native-runner-host.js'),'--suite',str(suite),'--report',str(root/'actual.json'),'--junit',str(root/'actual.xml'),'--html',str(root/'actual.html')],env=env,stdout=subprocess.PIPE,stderr=subprocess.PIPE)
 until(lambda:read_native_file_marker(root/'syscall.marker')or process.poll()is not None);assert process.poll()is None,(name,process.communicate())
 parts=read_native_file_marker(root/'syscall.marker');assert parts is not None;assert len(parts)==5;writer=int(parts[0]);assert state(writer)not in[None,'Z']and not(root/'actual.json').exists();return root,process,writer,parts

def finish(root,process,writer,code):
 stdout,stderr=process.communicate(timeout=12);(root/'stdout.bin').write_bytes(stdout);(root/'stderr.bin').write_bytes(stderr);assert process.returncode==code and not stderr,(root.name,process.returncode,stdout,stderr)
 value=json.loads((root/'actual.json').read_text());assert state(writer)is None;assert all(state(w['pid'])is None for w in value['workers']);rows.append({'scope':root.name,'actualExitCode':process.returncode,'actualWriterPid':writer,'report':str(root/'actual.json')});return value
