root,proc,writer,parts=start('own-step-deadline-cancels-held-file-and-keeps-next-step',"export default defineNativeSuite({tests:[{title:'actual own deadline',run:async(_,i)=>{await assert.rejects(i.step('timeout',async s=>{await s.attach('held',{body:'actual'})},{timeout:150}),/Step timeout of 150ms exceeded/);await i.step('next',async s=>{await s.attach('next',{body:'actual next'})})}}]});");v=finish(root,proc,writer,0);assert[s['status']for s in v['steps']]==['timedOut','passed']and len(v['attachments'])==1 and v['attachments'][0]['name']=='next'and not v['globalErrors']and len(files(root))==1
root,proc,writer,parts=start('real-directory-rollback-failure-cannot-be-excused',"export default defineNativeSuite({tests:[{title:'actual rollback infra',expectedFailure:true,run:async(_,i)=>{await assert.rejects(i.step('rollback',async s=>{await s.attach('held',{body:'actual inode'})},{timeout:200}),/Step timeout of 200ms exceeded/)}}]});",'directory');directory=pathlib.Path(bytes.fromhex(parts[4]).decode());assert parts[3]=='1'and directory.is_dir()and len(files(root))==1;directory.chmod(0o500)
try:
 v=finish(root,proc,writer,1);assert v['attempts'][0]['status']=='failed'and not v['attempts'][0]['expected']and not v['attachments']and any('rollback failed'in e for e in v['globalErrors'])and len(files(root))==1
finally:directory.chmod(0o700)
root,proc,writer,parts=start('real-owner-exit-zero-before-file-receipt-is-failure',"export default defineNativeSuite({tests:[{title:'actual owner exit',expectedFailure:true,run:async(_,i)=>{void i.step('owner gone',async s=>{void s.attach('held',{body:'actual'});await held();writeFileSync(process.env.ACTUAL_RAW_RETURN,'real step raw return')});while(!existsSync(process.env.ACTUAL_ALLOW_EXIT))await wait(1);process.exit(0)}}]});");until(lambda:(root/'raw-return').exists());assert proc.poll()is None;(root/'allow-exit').write_text('actual owner exits');v=finish(root,proc,writer,1);assert v['attempts'][0]['status']=='failed'and not v['attempts'][0]['expected']and not v['attachments']and not files(root)and v['workers'][0]['exitCode']==0 and v['workers'][0]['signal']is None and v['steps'][0]['status']!='passed'
root,proc,writer,parts=start('actual-SIGINT-retains-interruption-and-waitpid-file-fence',"export default defineNativeSuite({tests:[{title:'actual interruption',run:async(_,i)=>{await i.step('interrupted',async s=>{await s.attach('held',{body:'actual'})})}}]});");proc.send_signal(signal.SIGINT);v=finish(root,proc,writer,130);assert v['attempts'][0]['status']=='interrupted'and not v['attempts'][0]['expected']and not v['attachments']and not files(root)and v['steps'][0]['status']=='interrupted'
